import{r as e}from"./rolldown-runtime-hePW80VL.js";import{t}from"./jsx-runtime-NZYk81nU.js";var n=e(t()),r={title:`Settings`,description:`The eight tabs of the Settings page: General, Tools, Access, Security, Network, Automation, Appearance and About, what each field does and the config key behind it.`,icon:`Settings`},i={contents:[{heading:void 0,content:"**Settings** sits at the foot of the navigation and is split into eight tabs. The current tab is part of the address (such as `#/settings?tab=access`)."},{heading:void 0,content:`Every field **saves on its own** as it changes; there is no overall save button. Switches and selections save at once, text and number fields when you leave them (or press Enter), and list fields each time a value is added or removed. A save shows **Saved**; a field that needs a restart shows **Saved · Takes effect after a restart.** An invalid value shows the reason and leaves the configuration unchanged.`},{heading:void 0,content:"Apart from **Language** and **Appearance**, which are browser preferences, every setting is written to `config.json` in the data folder and applies to the running gateway at once. Each field below names its config key; the config file in full is described in Configuration file. Changes made from the command line or by editing the file need a server restart; changes made here do not (except the listening address and port)."},{heading:void 0,content:`A channel's own switch and network route are not here but in that channel's details on the Channels page.`},{heading:`general`,content:`The **General** section:`},{heading:`general`,content:`Setting`},{heading:`general`,content:`Config key`},{heading:`general`,content:`What it does`},{heading:`general`,content:`**Language**`},{heading:`general`,content:`None (browser)`},{heading:`general`,content:`**Auto detect (system language)**, English, 简体中文, 日本語`},{heading:`general`,content:`**Default model**`},{heading:`general`,content:"`server.default_model`"},{heading:`general`,content:`Used when a request does not name a model. Searchable; **None** means a request must name its model`},{heading:`general`,content:`The **Requests** section, limits applied to every request the gateway accepts:`},{heading:`general`,content:`Setting`},{heading:`general`,content:`Config key`},{heading:`general`,content:`Default`},{heading:`general`,content:`What it does`},{heading:`general`,content:`**Tries per request across accounts**`},{heading:`general`,content:"`server.max_account_retries`"},{heading:`general`,content:`3`},{heading:`general`,content:`How many accounts a request may rotate through before it fails; at least 1. The rotation rules are in Models and reasoning effort`},{heading:`general`,content:`**Maximum request size (bytes)**`},{heading:`general`,content:"`server.max_body_bytes`"},{heading:`general`,content:`16777216 (16 MiB)`},{heading:`general`,content:`Larger request bodies are refused. The arrows step by 1 MiB`},{heading:`general`,content:`The **Usage history** section:`},{heading:`general`,content:`Setting`},{heading:`general`,content:`Config key`},{heading:`general`,content:`Default`},{heading:`general`,content:`What it does`},{heading:`general`,content:`**Keep calls for (days)**`},{heading:`general`,content:"`server.stats_keep_days`"},{heading:`general`,content:`90`},{heading:`general`,content:"Older call records are removed; hourly totals are kept for 120 days and daily totals forever. The data is in `hoshimi.db` in the data folder. See Usage"},{heading:`general`,content:`The **Playground** section, how the Playground talks to models:`},{heading:`general`,content:`Setting`},{heading:`general`,content:`Config key`},{heading:`general`,content:`What it does`},{heading:`general`,content:`**System prompt**`},{heading:`general`,content:"`playground.system_prompt`"},{heading:`general`,content:`Sent first in every Playground chat, from its next message on. Empty sends none. A ready-made one: A system prompt for the Playground`},{heading:`general`,content:`**Title model**`},{heading:`general`,content:"`playground.title_model`"},{heading:`general`,content:`Names each new chat after its first reply. By default **The chat's own model**`},{heading:`general`,content:`**Image model**`},{heading:`general`,content:"`playground.vision_model`"},{heading:`general`,content:`Describes images for models that cannot read them. **Automatic** (the default): the first available model that reads images; **Off**: images are left out for models that cannot read them; or a particular model that reads images`},{heading:`general`,content:`The **Context** section, what happens as a Playground chat nears its model's context window:`},{heading:`general`,content:`Setting`},{heading:`general`,content:`Config key`},{heading:`general`,content:`Default`},{heading:`general`,content:`What it does`},{heading:`general`,content:`**Compact long chats automatically**`},{heading:`general`,content:"`playground.auto_compact`"},{heading:`general`,content:`On`},{heading:`general`,content:`Near the limit, a model summarises the chat so far and the chat goes on from the summary. A request the model refuses as too long is compacted and sent again either way`},{heading:`general`,content:`**Compact at (% of the window)**`},{heading:`general`,content:"`playground.compact_threshold`"},{heading:`general`,content:`85`},{heading:`general`,content:"50 to 95; sooner still when what is left could not hold a reply. Stored as a share (`0.85`)"},{heading:`general`,content:`**Summary model**`},{heading:`general`,content:"`playground.compact_model`"},{heading:`general`,content:`**The chat's own model**`},{heading:`general`,content:`Writes the summary when a chat is compacted`},{heading:`general`,content:`What these do in the Playground is in Playground.`},{heading:`tools`,content:`The Playground's built-in tools let models that make tool calls read and edit files, run commands and search the web. The tools switched on here are the tools of every chat; the approval mode set here is where new chats start, and each chat can change its own from the shield in its composer. The full guide is Playground tools.`},{heading:`tools`,content:`Commands and file edits run on this computer with the permissions of the user running Hoshimi. There is no sandbox: Automatic review has a model judge each command and edit first, and Ask first leaves every one to you.`},{heading:`tools`,content:"**Tools** (`playground.tools`, all on by default, for every chat):"},{heading:`tools`,content:`Switch`},{heading:`tools`,content:`Config value`},{heading:`tools`,content:`What it does`},{heading:`tools`,content:`**Read files**`},{heading:`tools`,content:"`read`"},{heading:`tools`,content:`Read text files and list folders`},{heading:`tools`,content:`**Edit files**`},{heading:`tools`,content:"`apply_patch`"},{heading:`tools`,content:`Create, change and delete files in the workspace`},{heading:`tools`,content:`**Run commands**`},{heading:`tools`,content:"`shell`"},{heading:`tools`,content:`Run a command and wait for its output`},{heading:`tools`,content:`**Background commands**`},{heading:`tools`,content:"`terminal`"},{heading:`tools`,content:`Start commands that keep running (servers, watchers), read their output, type into them and stop them`},{heading:`tools`,content:`**Search the web**`},{heading:`tools`,content:"`web_search`"},{heading:`tools`,content:`Search the web with DuckDuckGo, or with your own SearXNG`},{heading:`tools`,content:`**Read web pages**`},{heading:`tools`,content:"`web_fetch`"},{heading:`tools`,content:`Read public web pages as text; local and private network addresses are refused`},{heading:`tools`,content:`**How tools run**:`},{heading:`tools`,content:`Setting`},{heading:`tools`,content:`Config key`},{heading:`tools`,content:`Default`},{heading:`tools`,content:`What it does`},{heading:`tools`,content:`**When tools ask first**`},{heading:`tools`,content:"`playground.approval`"},{heading:`tools`,content:"**Automatic review** (`review`)"},{heading:`tools`,content:"**Automatic review**: a model judges commands, file changes and anything outside the workspace, and denies what's risky; you're asked when it can't decide; **Ask first** (`ask`): before commands, file changes and anything outside the workspace; **Ask outside the workspace** (`workspace`, formerly `auto`): commands and changes in the workspace run, reads and changes outside it ask; **Full access** (`full`): nothing asks. Calls that need leave are judged by the review model, or wait in the chat for your approval; the shield in a chat's composer changes the mode for that chat alone"},{heading:`tools`,content:`**Review model**`},{heading:`tools`,content:"`playground.review_model`"},{heading:`tools`,content:`**The chat’s own model**`},{heading:`tools`,content:`Judges tool calls under **Automatic review**. A fast, careful model is a good choice`},{heading:`tools`,content:`**Shell**`},{heading:`tools`,content:"`playground.shell`"},{heading:`tools`,content:"**Automatic** (`auto`)"},{heading:`tools`,content:'Where commands run when the model names no shell. **Automatic** is bash (`sh` without it; PowerShell on Windows, `cmd` without it), and its help text shows the one in effect ("Now bash"). The menu lists only the shells installed here; a model can still ask for any other of them'},{heading:`tools`,content:`**Workspace**`},{heading:`tools`,content:"`playground.workspace`"},{heading:`tools`,content:"`workspace` in the data folder"},{heading:`tools`,content:`Where tools start, and the only folder whose files they can edit. The help text shows the path in effect`},{heading:`tools`,content:`**SearXNG address**`},{heading:`tools`,content:"`playground.search_url`"},{heading:`tools`,content:`Empty`},{heading:`tools`,content:"Search with your own SearXNG (its JSON format turned on); must be an `http://` or `https://` address. Empty uses DuckDuckGo"},{heading:`access`,content:`The **Listening address** section (subtitle **Takes effect after a restart.**):`},{heading:`access`,content:`Setting`},{heading:`access`,content:`Config key`},{heading:`access`,content:`Default`},{heading:`access`,content:`What it does`},{heading:`access`,content:`**Host**`},{heading:`access`,content:"`server.host`"},{heading:`access`,content:"`127.0.0.1`"},{heading:`access`,content:`The address the server binds; by default only this machine can connect`},{heading:`access`,content:`**Port**`},{heading:`access`,content:"`server.port`"},{heading:`access`,content:`10600`},{heading:`access`,content:`The port the server tries first`},{heading:`access`,content:`**Use only this port**`},{heading:`access`,content:"`server.strict_port`"},{heading:`access`,content:`Off`},{heading:`access`,content:`Off: when the port is taken, the server tries the next free one, up to 65535 and then from 1024. On: a taken port makes the start fail`},{heading:`access`,content:"Under them, **Listening on** *address* shows where the server listens right now. When the port was taken and another was used, it adds **Port 10600 was taken, so the server is on 10601.**; that describes this run and needs no restart. After you save a new host or port, a banner at the top says **The server listens on a different address than the saved** *host*:*port*. **Restart it to apply.**; restart `hoshimi serve`."},{heading:`access`,content:`The **Keys** section. The two keys are independent; leaving one empty turns off key checks for its APIs:`},{heading:`access`,content:`Setting`},{heading:`access`,content:`Config key`},{heading:`access`,content:`Protects`},{heading:`access`,content:`**Tool access key**`},{heading:`access`,content:"`server.access_token`"},{heading:`access`,content:"Signing in to this interface, and the management API `/api/v1/*`, `/docs` and `/openapi.json`"},{heading:`access`,content:`**Model API key**`},{heading:`access`,content:"`server.model_api_key`"},{heading:`access`,content:"The model API `/v1/*`, for agents and other clients; they send it as `Authorization: Bearer` or `x-api-key`"},{heading:`access`,content:`Type a key and click **Save** (or press Enter); **Clear** removes it. Keys are stored in the config file and never shown again: the interface only says **A tool access key is set.** or **A model API key is set.** After you save or clear the tool access key, this browser switches to the new key by itself; other browsers have to sign in again.`},{heading:`access`,content:"Setting **Host** to an address other than this machine's (such as `0.0.0.0`) requires both a **Tool access key** and **Security › Allowed CIDRs**, or the save is refused: the gateway forwards requests with your upstream accounts' credentials. Setting a **Model API key** as well is recommended. The full steps are in Access and security."},{heading:`security`,content:`Who may connect. Press Enter after each value, or paste several at once (separated by spaces or commas); the × on a value removes it.`},{heading:`security`,content:`Setting`},{heading:`security`,content:`Config key`},{heading:`security`,content:`What it does`},{heading:`security`,content:`**Allowed CIDRs**`},{heading:`security`,content:"`security.allow_cidrs`"},{heading:`security`,content:"Networks that may connect, such as `10.0.0.0/8`. Loopback is always allowed"},{heading:`security`,content:`**Allowed hosts**`},{heading:`security`,content:"`security.allow_hosts`"},{heading:`security`,content:"`Host` names that may connect, such as `gateway.example.com`. Empty allows any host"},{heading:`security`,content:`**Allowed origins**`},{heading:`security`,content:"`security.allow_origins`"},{heading:`security`,content:"Browser pages on other origins that may call this API (CORS), such as `https://app.example.com`. Needs a tool access key first"},{heading:`security`,content:`Host and origin checks apply to requests with a key too; a key does not get around them. The detailed rules are in Access and security.`},{heading:`network`,content:"The default network route for every channel (config key `network`). Choose under **Route**:"},{heading:`network`,content:`Option`},{heading:`network`,content:`Effect`},{heading:`network`,content:`**Automatic (environment proxy)**`},{heading:`network`,content:"The default. Reads `HTTP_PROXY`, `HTTPS_PROXY`, `ALL_PROXY` and `NO_PROXY` (lowercase variables take precedence). **Use Windows system proxy when no environment proxy exists** can then be turned on"},{heading:`network`,content:`**Direct**`},{heading:`network`,content:`No proxy at all`},{heading:`network`,content:`**Proxy**`},{heading:`network`,content:`Enter an HTTP(S) or SOCKS5 address in **Proxy URL** and click **Save**; **Clear** goes back to automatic`},{heading:`network`,content:`The route is used for every request the gateway makes: model catalogue, inference, login, token refresh, balance, check-in, and the PyPI version check. A proxy address may hold a user name and password, so once saved the interface only says **Proxy configured; save to replace it.** A proxy that cannot be reached never falls back to a direct connection. Changes apply to new requests; streams already running finish on their original connections.`},{heading:`network`,content:`When one channel needs a different route, **Per-channel routes** takes you to the Channels page, where the channel's **Network** section overrides it. See Network and proxies.`},{heading:`automation`,content:`Two timers that keep the channels' accounts working:`},{heading:`automation`,content:`Switch`},{heading:`automation`,content:`Config key`},{heading:`automation`,content:`Default`},{heading:`automation`,content:`What it does`},{heading:`automation`,content:`**Daily check-in**`},{heading:`automation`,content:"`server.auto_checkin`"},{heading:`automation`,content:`On`},{heading:`automation`,content:`Claims each station's free credits once a day. **Today's check-in** under it says whether today is done, and the last round's result`},{heading:`automation`,content:`**Credential renewal**`},{heading:`automation`,content:"`server.auto_refresh`"},{heading:`automation`,content:`On`},{heading:`automation`,content:`Renews tokens before they expire: every 30 minutes, accounts expiring within the hour are renewed`},{heading:`automation`,content:"A pure gateway that should make no background requests can turn them off. Manual check-in and renewal are on the Channels page, with the rules in Channels. For one run, `hoshimi serve --no-checkin --no-refresh` turns them off at start; see Command reference."},{heading:`appearance`,content:`These options are kept in the current browser and affect only it:`},{heading:`appearance`,content:`Setting`},{heading:`appearance`,content:`Options`},{heading:`appearance`,content:`**Theme**`},{heading:`appearance`,content:`**Light**, **Dark**, **System** (the default). The theme button in the top bar switches it too`},{heading:`appearance`,content:`**Colour**`},{heading:`appearance`,content:`Pick a colour; the interface's palette is generated from it`},{heading:`appearance`,content:`**Contrast**`},{heading:`appearance`,content:`**Standard** (the default), **Medium**, **High**`},{heading:`appearance`,content:`**Motion**`},{heading:`appearance`,content:`**Follow system** (the default) or **Reduced**: short fades instead of slides and growth`},{heading:`appearance`,content:`**Images and video from other sites**`},{heading:`appearance`,content:`**Ask first** (the default): media a Playground reply points to on another site waits behind a button naming the site; **Always load**`},{heading:`about`,content:`Item`},{heading:`about`,content:`Contents`},{heading:`about`,content:`**Version**`},{heading:`about`,content:`The Hoshimi version running`},{heading:`about`,content:`**Data directory**`},{heading:`about`,content:`The folder holding the configuration, the database and the workspace`},{heading:`about`,content:`**Config file**`},{heading:`about`,content:"The full path of `config.json`"},{heading:`about`,content:`**Database**`},{heading:`about`,content:"The full path of `hoshimi.db`: usage, check-in history, probe verdicts and Playground chats are all in it"},{heading:`about`,content:"**Copy config path** copies the config file's path to the clipboard. With no tool access key there is also **API reference**, which opens the server's own API documentation (`/docs`). Where the data folder is and what is in it: Data folder and paths; on the command line, `hoshimi config path` prints the config file's path."},{heading:`settings-that-are-not-in-the-interface`,content:"A few settings are only in `config.json`, such as `server.check_updates` (whether to ask PyPI for new versions) and the options in `providers.<id>.options` other than the network route and the Cline login method. Change them with `hoshimi config set` and restart the server:"},{heading:`settings-that-are-not-in-the-interface`,content:`Every config key is in Configuration file.`}],headings:[{id:`general`,content:`General`},{id:`tools`,content:`Tools`},{id:`access`,content:`Access`},{id:`security`,content:`Security`},{id:`network`,content:`Network`},{id:`automation`,content:`Automation`},{id:`appearance`,content:`Appearance`},{id:`about`,content:`About`},{id:`settings-that-are-not-in-the-interface`,content:`Settings that are not in the interface`}]},a=[{depth:2,url:`#general`,title:(0,n.jsx)(n.Fragment,{children:`General`})},{depth:2,url:`#tools`,title:(0,n.jsx)(n.Fragment,{children:`Tools`})},{depth:2,url:`#access`,title:(0,n.jsx)(n.Fragment,{children:`Access`})},{depth:2,url:`#security`,title:(0,n.jsx)(n.Fragment,{children:`Security`})},{depth:2,url:`#network`,title:(0,n.jsx)(n.Fragment,{children:`Network`})},{depth:2,url:`#automation`,title:(0,n.jsx)(n.Fragment,{children:`Automation`})},{depth:2,url:`#appearance`,title:(0,n.jsx)(n.Fragment,{children:`Appearance`})},{depth:2,url:`#about`,title:(0,n.jsx)(n.Fragment,{children:`About`})},{depth:2,url:`#settings-that-are-not-in-the-interface`,title:(0,n.jsx)(n.Fragment,{children:`Settings that are not in the interface`})}];func